query CustomerByCustomerAccessToken($customerAccessToken: String!) {
  customer(customerAccessToken: $customerAccessToken) {
    id
    firstName
    lastName
    acceptsMarketing
    email
    phone
    tags
    metafields(
      identifiers: [{key: "customer_string", namespace: "subscriptions"}, {key: "subscription_frequency", namespace: "club"}, {key: "subscription_frequency", namespace: "club"}, {key: "is_subscribed", namespace: "club"}, {key: "tier", namespace: "club"}, {key: "subscribe_to", namespace: "club"}, {key: "credits", namespace: "club"}, {key: "legacy", namespace: "club"}, {key: "legacy_expires_at", namespace: "club"}]
    ) {
      namespace
      key
      value
    }
    orders(first: 100, reverse: true) {
      edges {
        node {
          id
          orderNumber
          processedAt
          shippingAddress {
            address1
            address2
            city
            company
            country
            countryCodeV2
            formatted
            formattedArea
            zip
            name
            firstName
            lastName
            phone
            id
          }
          subtotalPrice {
            amount
          }
          totalShippingPrice {
            amount
          }
          totalPriceV2 {
            amount
          }
          fulfillmentStatus
          shippingDiscountAllocations {
            allocatedAmount {
              amount
            }
          }
          canceledAt
          customAttributes {
            key
            value
          }
          lineItems(first: 100, reverse: true) {
            edges {
              node {
                title
                discountedTotalPrice {
                  amount
                }
                originalTotalPrice {
                  amount
                }
                variant {
                  title
                  imagesm: image {
                    url(transform: {maxWidth: 300})
                  }
                  imagemd: image {
                    url(transform: {maxWidth: 768})
                  }
                  imagelg: image {
                    url(transform: {maxWidth: 1280})
                  }
                  price {
                    amount
                  }
                  product {
                    id
                    title
                    handle
                    productType
                    images(first: 10) {
                      edges {
                        node {
                          url(transform: {maxWidth: 1280})
                          altText
                        }
                      }
                    }
                    imagesmd: images(first: 10) {
                      edges {
                        node {
                          url(transform: {maxWidth: 768})
                        }
                      }
                    }
                    imagessm: images(first: 10) {
                      edges {
                        node {
                          url(transform: {maxWidth: 300})
                          altText
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
    defaultAddress {
      address1
      address2
      city
      company
      country
      countryCodeV2
      formatted
      formattedArea
      zip
      name
      firstName
      lastName
      phone
      id
    }
    addresses(first: 10, reverse: true) {
      edges {
        node {
          address1
          address2
          city
          company
          country
          countryCodeV2
          formatted
          formattedArea
          zip
          name
          firstName
          lastName
          phone
          id
        }
      }
    }
  }
}
